1386	/// Check if a battlefield object matches a TargetFilter.
1387	/// Used by generate_ability_targets to filter targets for activated abilities.
1388	fn matches_target_filter(obj: &crate::state::GameObject, filter: &crate::cards::TargetFilter) -> bool {
1389	    use crate::cards::TargetFilter;
1390	    match filter {
1391	        TargetFilter::Any => true,
1392	        TargetFilter::HasCardType(types) => {
1393	            types.iter().any(|t| obj.card_types.contains(t))
1394	        }
1395	        TargetFilter::Noncreature => obj.power.is_none(),
1396	        TargetFilter::Nonblack => !obj.colors.contains(&crate::types::Color::Black),
1397	        TargetFilter::HasSubtype(subtype) => obj.subtypes.iter().any(|s| s == subtype),
1398	        _ => true, // Other filters not yet needed for abilities.
1399	    }
1400	}
